def attribute_existing_uploads(apps, schema_editor):
    """Best effort for uploads made before the team was recorded: the team
    the uploader joined most recently before the upload, else their earliest
    team. Leaving a team deletes its membership row, so an upload made in a
    team the user has left since is attributed to a later team or not at all
    (team stays null and the upload counts for nobody)."""
    Upload = apps.get_model("core", "Upload")
    TeamMembership = apps.get_model("core", "TeamMembership")
    db = schema_editor.connection.alias
    memberships = {}
    for membership in TeamMembership.objects.using(db).order_by("created_at", "id"):
        memberships.setdefault(membership.user_id, []).append(membership)
    for upload in Upload.objects.using(db).filter(team__isnull=True):
        mine = memberships.get(upload.user_id) or []
        before = [m for m in mine if m.created_at <= upload.created_at]
        chosen = before[-1] if before else (mine[0] if mine else None)
        if chosen is not None:
            Upload.objects.using(db).filter(pk=upload.pk).update(team_id=chosen.team_id)


